function threadRow(t){return `<div class="list-row"><button type="button" class="avatar" data-action="open-thread" data-value="${t.id}" aria-label="Abrir conversa com ${esc(t.who)}">${esc(t.ini||initals(t.who))}</button><button type="button" class="txt" data-action="open-thread" data-value="${t.id}"><b>${esc(t.who)}${t.unread?' · nova':''}${t.pinned?' · fixada':''}</b><small>${esc(threadTitle(t))}</small><small>${esc(t.msgs.at(-1)?.t||'Comece a conversa')}</small></button>${iconBtn('more_vert','thread-menu',t.id,'Opções da conversa')}</div>`;}
function renderThreads(){const ts=state.threads.filter(t=>t.city===state.city&&!t.deleted).sort((a,b)=>(b.pinned?1:0)-(a.pinned?1:0)||(b.updatedAt||0)-(a.updatedAt||0));return `<div class="page-head"><div><h1>Conversas</h1><p>Contatos sobre anúncios e serviços da cidade.</p></div></div>${readonlyHtml()}${ts.length?pagedHtml('threads',state.city,ts,threadRow,{noun:'conversas',art:'as',wrap:'list'}):empty('Nenhuma conversa ainda','Abra um anúncio ou negócio e toque em “Tenho interesse” ou “Pedir orçamento”.','chat_bubble','home','Explorar a cidade')}`;}
function threadTitle(t){return t.about.type==='item'?itemById(t.about.id)?.title||t.snapshot?.title||'Anúncio encerrado':t.about.type==='biz'?bizById(t.about.id)?.name||t.snapshot?.title||'Negócio':t.about.t||'Conversa da comunidade';}
function renderChat(){
 const t=messagingThread(route.id);if(!t)return unavailable();
 const ref=t.about.type==='item'?itemById(t.about.id):t.about.type==='biz'?bizById(t.about.id):null,p=image(ref?.photos?.[0]||t.snapshot?.photo);
 const disabled=readonly()||!state.profile.verified,draft=messagingDrafts.get(t.id)??t.draft??'';
 // No celular: sem rótulo flutuante, sem dica de teclado e sem contador fixo (o limite continua
 // valendo no envio). No desktop, como antes.
 const phone=innerWidth<720,input=phone?`<md-outlined-text-field id="chat-input" class="chat-pill" placeholder="Mensagem" aria-label="Mensagem" value="${esc(draft)}" type="textarea" rows="1" ${disabled?'disabled':''}></md-outlined-text-field>`:field('chat-input','Mensagem',draft,`type="textarea" rows="1" maxlength="2000" supporting-text="Enter envia · Shift+Enter adiciona uma linha" ${disabled?'disabled':''}`);
 actionsBar(`<div style="display:grid;gap:6px;width:100%;max-width:var(--max);margin:auto;min-width:0">${disabled?'':messagingQuickRepliesHtml(t)}<div class="compose-bar">${input}${iconBtn('send','send-message',t.id,'Enviar mensagem fictícia')}</div></div><p id="chat-status" class="form-note" role="status" aria-live="polite" aria-atomic="true">${readonly()?`Você está consultando ${esc(state.city)}. Envie mensagens na sua cidade, ${esc(state.homeCity)}.`:!state.profile.verified?'O perfil de teste precisa estar verificado para enviar mensagens.':''}</p>`);
 return `<div class="page-head chat-head"><div class="row"><span class="avatar">${esc(t.ini||initals(t.who))}</span><div><h1 id="chat-heading" tabindex="-1" style="font-size:23px">${esc(t.who)}</h1><p>Conversa sobre ${esc(threadTitle(t))}</p></div></div>${iconBtn('more_vert','thread-menu',t.id,'Opções da conversa')}</div><p class="form-note">Demonstração: mensagens fictícias salvas apenas neste navegador. Nenhuma mensagem real é enviada.</p><button type="button" class="conversation-context" data-action="thread-origin" data-value="${t.id}">${p?`<img src="${p}" alt="">`:icon('info')}<span class="grow"><b class="small">${esc(threadTitle(t))}</b><br><span class="tiny muted">Ver a origem do contato</span></span>${icon('chevron_right')}</button><p class="chat-safety">${icon('verified_user')}<span>Nunca pague adiantado nem envie documentos pelo chat. Combine a entrega em local público.</span></p><div class="message-list chat-list" id="message-list" aria-label="Histórico da conversa fictícia">${chatMessagesHtml(t)||empty('Combine os detalhes por aqui','Descreva o que você procura e confirme preço, disponibilidade e horário.','chat_bubble')}</div>`;
}

// Respostas rápidas (Rodada 10): md-suggestion-chip preenche o rascunho; nunca envia sozinho.
function messagingQuickReplies(t){return t.about?.type==='item'?['O anúncio ainda está disponível?','Podemos combinar a retirada?','Aceita uma proposta?']:['Pode me passar um orçamento?','Qual o horário de atendimento?','Atende no meu bairro?'];}
function messagingQuickRepliesHtml(t){return `<md-chip-set class="quick-replies" aria-label="Respostas rápidas" style="display:flex;flex-wrap:nowrap;overflow-x:auto;gap:8px;padding-bottom:8px">${messagingQuickReplies(t).map((x,i)=>`<md-suggestion-chip label="${esc(x)}" data-action="quick-reply" data-value="${t.id}|${i}"></md-suggestion-chip>`).join('')}</md-chip-set>`;}
